 perform public.distribution_prepare_submission_email(sid,(job->>'lease')::uuid,'{"text":"stable fixture"}');
 perform public.distribution_finish_submission_email(sid,(job->>'lease')::uuid,false);
 if not exists(select 1 from public.game_submissions where id=sid) then raise exception 'Failed mail lost submission'; end if;
 update public.game_submission_notifications set next_attempt_at=now()-interval '1 second' where submission_id=sid;
 again:=public.distribution_claim_submission_email(sid);
