 update public.game_submission_notifications set sent_at=null,attempts=0,first_attempt_at=null,created_at=now()-interval '3 days',next_attempt_at=now()-interval '1 second' where submission_id=sid;
 job:=public.distribution_claim_submission_email(sid);
 if job is null then raise exception 'Old unattempted notification lost'; end if;
