 again:=public.distribution_claim_submission_email(sid);
 if again is null or again->>'lease'=job->>'lease' then raise exception 'Expired lease not recovered'; end if;
 perform public.distribution_expect_failure(format('select public.distribution_finish_submission_email(%L,%L,true)',sid,job->>'lease'));
 perform public.distribution_finish_submission_email(sid,(again->>'lease')::uuid,false);
