 update public.game_submission_notifications set attempts=1,first_attempt_at=now()-interval '25 hours',last_error=null where submission_id=sid;
 if public.distribution_claim_submission_email(sid) is not null then raise exception 'Provider idempotency window exceeded'; end if;
 if (select last_error from public.game_submission_notifications where submission_id=sid)<>'attention_required' then raise exception 'Expired notification not flagged'; end if;
 if position('PrivateFirst' in (select to_jsonb(g)::text from public.games g where id=game))>0 then raise exception 'Private contact in catalogue'; end if;
end $$;
